import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { App } from 'aws-cdk-lib';
import { createStack } from './product.mjs';

// Trusted, private native Node preview. It synthesizes the actual product stack
// locally and returns only bounded counts; no CloudFormation template or AWS
// API call leaves this module. The gateway Worker currently cannot execute it.
export async function preview({ configuration, selected_components }) {
  let outdir;
  try {
    if (!Array.isArray(selected_components) || selected_components.length !== 1 || selected_components[0] !== 'stack') {
      return { ok: false, status: 'invalid', slug: 'cloudwatch-monitoring-facade', selected_components: [], resource_count: 0, diagnostic_codes: ['invalid_selection'] };
    }
    if (!configuration || configuration.language !== 'javascript') {
      return { ok: false, status: 'invalid', slug: 'cloudwatch-monitoring-facade', selected_components: ['stack'], resource_count: 0, diagnostic_codes: ['configuration_invalid'] };
    }
    outdir = mkdtempSync(join(tmpdir(), 'secondwind-private-cdk-preview-'));
    const app = new App({ outdir, analyticsReporting: false });
    createStack(app, { configuration, selected_components });
    const assembly = app.synth();
    const resource_count = assembly.stacks.reduce((sum, stack) => sum + Object.keys(stack.template?.Resources || {}).length, 0);
    return { ok: true, status: 'complete', slug: 'cloudwatch-monitoring-facade', selected_components: ['stack'], resource_count };
  } catch {
    return { ok: false, status: 'invalid', slug: 'cloudwatch-monitoring-facade', selected_components: ['stack'], resource_count: 0, diagnostic_codes: ['validation_failed'] };
  } finally {
    if (outdir) rmSync(outdir, { recursive: true, force: true });
  }
}

import { App, Stack } from 'aws-cdk-lib';
import * as lambda from 'aws-cdk-lib/aws-lambda';
import * as dynamodb from 'aws-cdk-lib/aws-dynamodb';
import { MonitoringFacade } from 'cdk-monitoring-constructs';

export function createStack(app, { configuration: c }) {
  if (!c || !/^arn:[^:]+:lambda:[^:]*:\d{12}:function:.+$/.test(c.lambda_function_arn)
      || typeof c.table_name !== 'string' || !c.table_name || !c.dashboard_name) {
    throw new Error('invalid_configuration');
  }
  const stack = new Stack(app, 'CloudWatchMonitoringStack');
  const lambdaFunction = lambda.Function.fromFunctionArn(stack, 'MonitoredFunction', c.lambda_function_arn);
  const table = dynamodb.Table.fromTableName(stack, 'MonitoredTable', c.table_name);
  const facade = new MonitoringFacade(stack, 'Monitoring', {
    alarmFactoryDefaults: { actionsEnabled: false, alarmNamePrefix: c.dashboard_name },
  });
  facade.monitorLambdaFunction({ lambdaFunction });
  facade.monitorDynamoTable({ table });
  return stack;
}

export function synthesize(configuration) {
  const app = new App({ analyticsReporting: false });
  createStack(app, { configuration });
  return app.synth();
}

